import 'package:flutter/material.dart';
import '../models/task.dart';
import '../widgets/category_selector.dart';

class AddTaskScreen extends StatefulWidget { final Task? task; const AddTaskScreen({super.key,this.task}); @override State<AddTaskScreen> createState()=>_AddTaskScreenState(); }
class _AddTaskScreenState extends State<AddTaskScreen>{late final TextEditingController title,desc; late TaskPriority priority; late TaskCategory category; DateTime? due;
 @override void initState(){super.initState();final t=widget.task;title=TextEditingController(text:t?.title);desc=TextEditingController(text:t?.description);priority=t?.priority??TaskPriority.medium;category=t?.category??TaskCategory.personal;due=t?.dueDate;}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.task==null?'New focus':'Edit focus'),actions:[IconButton(onPressed:(){if(title.text.trim().isEmpty)return;final t=widget.task??Task(id:DateTime.now().microsecondsSinceEpoch.toString(),title:title.text.trim());t.title=title.text.trim();t.description=desc.text.trim();t.priority=priority;t.category=category;t.dueDate=due;Navigator.pop(context,t);},icon:const Icon(Icons.check_rounded))]),body:ListView(padding:const EdgeInsets.fromLTRB(22,8,22,30),children:[TextField(controller:title,autofocus:true,style:const TextStyle(fontSize:26,fontWeight:FontWeight.w700),decoration:const InputDecoration(hintText:'What needs your attention?',border:InputBorder.none)),TextField(controller:desc,maxLines:3,decoration:const InputDecoration(hintText:'Add a little context…',border:InputBorder.none)),const SizedBox(height:24),const Text('CATEGORY',style:TextStyle(fontSize:11,fontWeight:FontWeight.w800,letterSpacing:1.5)),const SizedBox(height:10),CategorySelector(selected:category,onChanged:(v)=>setState(()=>category=v)),const SizedBox(height:25),const Text('PRIORITY',style:TextStyle(fontSize:11,fontWeight:FontWeight.w800,letterSpacing:1.5)),Wrap(spacing:8,children:TaskPriority.values.map((p)=>ChoiceChip(label:Text('● ${p.name[0].toUpperCase()+p.name.substring(1)}'),selected:priority==p,onSelected:(_)=>setState(()=>priority=p))).toList()),const SizedBox(height:25),ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.schedule_rounded),title:Text(due==null?'Add due date & time':'${due!.day}/${due!.month}/${due!.year}  ${due!.hour.toString().padLeft(2,'0')}:${due!.minute.toString().padLeft(2,'0')}'),onTap:()async{final d=await showDatePicker(context:context,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:3650)),initialDate:due??DateTime.now());if(d==null)return;final t=await showTimePicker(context:context,initialTime:TimeOfDay.fromDateTime(due??DateTime.now()));if(t!=null)setState(()=>due=DateTime(d.year,d.month,d.day,t.hour,t.minute));})])); }
